func rptPlan(emonT *testing.T, file []byte, policy int32, scope int32, pl *port.Cells, fw *port.Cells, fl *port.Cells, et *port.Cells) int32 {
	// Run a document through the document pass up to the text layer's health and plan it: `pl` has the plan (its page rows, then the witness rows), `fw` `fl` `et` the flow.
	// Every page is of kind born-digital here (the corpus documents are). Answers the number of pages.
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var cx *port.Cells = port.NewCells()
	var ox *port.Cells = port.NewCells()
	var cs *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var f0 *port.Cells = port.NewCells()
	var f1 *port.Cells = port.NewCells()
	var f2 *port.Cells = port.NewCells()
	var f3 *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var mk *port.Cells = port.NewCells()
	var fnt *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var pa *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var gx *port.Cells = port.NewCells()
	var epages *port.Cells = port.NewCells()
	var feats *port.Cells = port.NewCells()
	var fa *port.Cells = port.NewCells()
	var hl *port.Cells = port.NewCells()
	var sc *port.Cells = port.NewCells()
	var s1 *port.Cells = port.NewCells()
	var s2 *port.Cells = port.NewCells()
	var src *port.Src = port.SrcOfBlob(file)
	var o int32 = pdfdoc.PdOpen(src, ar, dc, a, b, st)
	var status int32 = 0
	var np int32 = 0
	var i int32 = 0
	var k int32 = 0
	port.AssertEqAt(emonT, o, 0, "the file opened", 0)
	status = pdfcontent.PcDocument(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx)
	port.AssertEqAt(emonT, status, 0, "the file ran", 0)
	tlhealth.ThRun(pg, gl, et, mk, fnt, wd, ln, im, epages, feats, fw, fl, fa, hl, sc)
	np = pdfdoc.PdPgCount(pg)
	for i < np {
		port.CellsPush(pl, 2)
		k = 1
		for k < rasterplan.RpW() {
			port.CellsPush(pl, 0)
			k += 1
		}
		i += 1
	}
	rasterplan.RpPlan(np, policy, scope, fw, fl, et, hl, im, pg, pl, s1, s2)
	return np
}

func rptRow(pl *port.Cells, page int32, f int32) int32 {
	return port.CellsAt(pl, (page*rasterplan.RpW())+f)
}

func TestAlwaysAndFullAsksEveryPageWhole(emonT *testing.T) {
	var pl *port.Cells = port.NewCells()
	var fw *port.Cells = port.NewCells()
	var fl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var np int32 = rptPlan(emonT, port.TestFile("corpus/synth/pdf/h-plain.pdf"), 2, rasterplan.RpScopeFull(), pl, fw, fl, et)
	var i int32 = 0
	port.AssertEq(emonT, np, 2, "two pages")
	for i < np {
		port.AssertEq(emonT, rptRow(pl, i, rasterplan.RpFAsk()), rasterplan.RpAskFull(), "the whole render with its text")
		port.AssertEq(emonT, rptRow(pl, i, rasterplan.RpFWn()), 0, "no witness line")
		port.AssertEq(emonT, rptRow(pl, i, rasterplan.RpFScripts())&1, 1, "the page's script is Latin")
		i += 1
	}
	port.AssertEq(emonT, port.CellsLen(pl), np*rasterplan.RpW(), "no witness row")
}

func TestWitnessReadsTheRenderWithoutTheTextAndAFewLinesOfEveryFont(emonT *testing.T) {
	var pl *port.Cells = port.NewCells()
	var fw *port.Cells = port.NewCells()
	var fl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var np int32 = rptPlan(emonT, port.TestFile("corpus/synth/pdf/h-plain.pdf"), 2, rasterplan.RpScopeWitness(), pl, fw, fl, et)
	var i int32 = 0
	var j int32 = 0
	var at int32 = 0
	var l int32 = 0
	var same int32 = 0
	var q int32 = 0
	port.AssertEq(emonT, np, 2, "two pages")
	for i < np {
		port.AssertEq(emonT, rptRow(pl, i, rasterplan.RpFAsk()), rasterplan.RpAskWitness(), "witness")
		port.AssertThat(emonT, rptRow(pl, i, rasterplan.RpFWn()) > 0, "a page of text has witness lines")
		port.AssertThat(emonT, rptRow(pl, i, rasterplan.RpFWn()) <= rasterplan.RpWitnessMax(), "within the page's ceiling")
		j = 0
		for j < rptRow(pl, i, rasterplan.RpFWn()) {
			at = rptRow(pl, i, rasterplan.RpFWat()) + (j * rasterplan.RpWw())
			l = port.CellsAt(pl, at+1)
			port.AssertEq(emonT, port.CellsAt(pl, at), i, "the row's page")
			port.AssertEq(emonT, evidence.LnGet(fl, l, evidence.LhPage()), i+1, "its line is on that page")
			port.AssertEq(emonT, evidence.LnGet(fl, l, evidence.LhRot()), 0, "upright")
			port.AssertEq(emonT, evidence.WdGet(fw, evidence.LnGet(fl, l, evidence.LhFirst()), evidence.WfFont()), port.CellsAt(pl, at+6), "of the row's font")
			// no line twice, and at most `witness-lines` a font
			same = 0
			q = 0
			for q < rptRow(pl, i, rasterplan.RpFWn()) {
				if port.CellsAt(pl, rptRow(pl, i, rasterplan.RpFWat())+((q*rasterplan.RpWw())+1)) == l {
					same += 1
				}
				q += 1
			}
			port.AssertEq(emonT, same, 1, "a line once")
			j += 1
		}
		i += 1
	}
}

func rptField(emonT *testing.T, file []byte, policy int32, scope int32, page int32, f int32) int32 {
	// Plan the document and answer one field of one page's row.
	var pl *port.Cells = port.NewCells()
	var fw *port.Cells = port.NewCells()
	var fl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	rptPlan(emonT, file, policy, scope, pl, fw, fl, et)
	return rptRow(pl, page, f)
}

func rptAsked(emonT *testing.T, file []byte, policy int32, scope int32, pages int32, what int32) int32 {
	// The pages (of the first `pages`) whose `ask` is `what`.
	var i int32 = 0
	var n int32 = 0
	for i < pages {
		if rptField(emonT, file, policy, scope, i, rasterplan.RpFAsk()) == what {
			n += 1
		}
		i += 1
	}
	return n
}

func TestAutoAsksOnlyWhereTheTextLayerCallsForIt(emonT *testing.T) {
	port.AssertEq(emonT, rptAsked(emonT, port.TestFile("corpus/synth/pdf/h-plain.pdf"), 1, rasterplan.RpScopeFull(), 2, rasterplan.RpAskNone()), 2, "a healthy document asks nothing under auto")
	port.AssertThat(emonT, rptAsked(emonT, port.TestFile("corpus/synth/pdf/tl-broken-unmapped.pdf"), 1, rasterplan.RpScopeFull(), 2, rasterplan.RpAskFull()) > 0, "a page with an unmapped font is asked, as full")
	port.AssertEq(emonT, rptField(emonT, port.TestFile("vis/ocrlayer.pdf"), 1, rasterplan.RpScopeWitness(), 0, rasterplan.RpFAsk()), rasterplan.RpAskFull(), "hidden text under auto is asked, as full, whatever the scope")
	port.AssertEq(emonT, rptField(emonT, port.TestFile("corpus/synth/pdf/h-plain.pdf"), 0, rasterplan.RpScopeFull(), 0, rasterplan.RpFAsk()), rasterplan.RpAskNone(), "never plans nothing")
}

func TestTheScriptsOfTheTextLayer(emonT *testing.T) {
	port.AssertEq(emonT, rasterplan.RpScriptOf(65), 0, "A is Latin")
	port.AssertEq(emonT, rasterplan.RpScriptOf(233), 0, "e acute is Latin")
	port.AssertEq(emonT, rasterplan.RpScriptOf(215), -1, "the multiplication sign is no letter")
	port.AssertEq(emonT, rasterplan.RpScriptOf(1103), 1, "Cyrillic")
	port.AssertEq(emonT, rasterplan.RpScriptOf(945), 2, "Greek")
	port.AssertEq(emonT, rasterplan.RpScriptOf(1575), 3, "Arabic")
	port.AssertEq(emonT, rasterplan.RpScriptOf(1488), 4, "Hebrew")
	port.AssertEq(emonT, rasterplan.RpScriptOf(2325), 5, "Devanagari")
	port.AssertEq(emonT, rasterplan.RpScriptOf(20013), 6, "Han")
	port.AssertEq(emonT, rasterplan.RpScriptOf(54620), 7, "Hangul")
	port.AssertEq(emonT, rasterplan.RpScriptOf(12354), 8, "Hiragana")
	port.AssertEq(emonT, rasterplan.RpScriptOf(3585), 9, "Thai")
	port.AssertEq(emonT, rasterplan.RpScriptOf(48), -1, "a digit belongs to no script")
	port.AssertEq(emonT, rptField(emonT, port.TestFile("corpus/synth/pdf/script-hebrew.pdf"), 2, rasterplan.RpScopeFull(), 0, rasterplan.RpFScripts())&16, 16, "a Hebrew page asks for the Hebrew script")
	port.AssertEq(emonT, rptField(emonT, port.TestFile("corpus/synth/pdf/script-devanagari.pdf"), 2, rasterplan.RpScopeFull(), 0, rasterplan.RpFScripts())&32, 32, "a Devanagari page asks for it")
	port.AssertEq(emonT, rptField(emonT, port.TestFile("corpus/synth/pdf/h-plain.pdf"), 2, rasterplan.RpScopeFull(), 0, rasterplan.RpFScripts())&1, 1, "a Latin page asks for Latin")
}

func rptWord(et *port.Cells, a int32, b int32, c int32, d int32, e int32) int32 {
	// Five code points appended to the text arena; answers where they start.
	var at int32 = port.CellsLen(et)
	evidence.EtxAppendCp(et, a)
	evidence.EtxAppendCp(et, b)
	evidence.EtxAppendCp(et, c)
	evidence.EtxAppendCp(et, d)
	evidence.EtxAppendCp(et, e)
	return at
}

func rptWitnessRow(pl *port.Cells, line int32, font int32) int32 {
	port.CellsPush(pl, 0)
	port.CellsPush(pl, line)
	port.CellsPush(pl, 100)
	port.CellsPush(pl, 100)
	port.CellsPush(pl, 1200)
	port.CellsPush(pl, 200)
	port.CellsPush(pl, font)
	port.CellsPush(pl, 0)
	return 0
}

func rptReading(oruns *port.Cells, owords *port.Cells, request int32, t0 int32, t1 int32) int32 {
	// An OCR run of two five-letter words (their text at `t0`, `t1` in the text arena) answering `request`.
	var run int32 = evidence.OrNew(oruns, 1, 0)
	var w0 int32 = port.CellsLen(owords)
	evidence.OwNew(owords, 1, 100, 100, 600, 200, 100, 100, 600, 200, 0, 0, t0, 5, 0, 900, -1)
	evidence.OwNew(owords, 1, 700, 100, 1200, 200, 700, 100, 1200, 200, 0, 0, t1, 5, 0, 900, -1)
	evidence.OrSet(oruns, run, evidence.OrfRequest(), request)
	evidence.OrSet(oruns, run, evidence.OrfWfirst(), w0/28)
	evidence.OrSet(oruns, run, evidence.OrfWcount(), 2)
	return run
}

func TestWitnessesThatDisagreeWithTheTextEscalateThePage(emonT *testing.T) {
	var pl *port.Cells = port.NewCells()
	var fw *port.Cells = port.NewCells()
	var fl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var oruns *port.Cells = port.NewCells()
	var owords *port.Cells = port.NewCells()
	var scr *port.Cells = port.NewCells()
	var ta *port.Cells = port.NewCells()
	var tb *port.Cells = port.NewCells()
	var tt *port.Cells = port.NewCells()
	var tw0 int32 = rptWord(et, 104, 101, 108, 108, 111)
	var tw1 int32 = rptWord(et, 119, 111, 114, 108, 100)
	var rw0 int32 = rptWord(et, 104, 101, 108, 108, 111)
	var rw1 int32 = rptWord(et, 119, 111, 114, 108, 100)
	var bw0 int32 = rptWord(et, 120, 121, 122, 122, 121)
	var bw1 int32 = rptWord(et, 113, 119, 101, 114, 116)
	// the text layer: one line of two words, "hello world", font 7; two witness rows read that same line
	evidence.WdNew(fw, 1, 100, 100, 600, 200, 100, 100, 600, 200, 0, 0, tw0, 5, 0, 900, -1)
	evidence.WdNew(fw, 1, 700, 100, 1200, 200, 700, 100, 1200, 200, 0, 0, tw1, 5, 0, 900, -1)
	evidence.WdSet(fw, 0, evidence.WfFont(), 7)
	evidence.WdSet(fw, 1, evidence.WfFont(), 7)
	evidence.LnNew(fl, 1, 100, 100, 1200, 200, 100, 100, 1200, 200, 0, 0, 0, 2)
	rptWitnessRow(pl, 0, 7)
	rptWitnessRow(pl, 0, 7)
	// two readings that say "hello world": the font's witnesses agree
	rptReading(oruns, owords, rasterplan.RiWitness()+0, rw0, rw1)
	rptReading(oruns, owords, rasterplan.RiWitness()+1, rw0, rw1)
	port.AssertEq(emonT, rasterplan.RpWeak(2, 0, pl, fw, fl, et, rasterplan.RiWitness(), 0, 2, owords, oruns, scr, ta, tb, tt), 0, "agreeing witnesses: not weak")
	// two readings that do not: weak
	port.CellsDrop(oruns, 0)
	port.CellsDrop(owords, 0)
	rptReading(oruns, owords, rasterplan.RiWitness()+0, bw0, bw1)
	rptReading(oruns, owords, rasterplan.RiWitness()+1, bw0, bw1)
	port.AssertEq(emonT, rasterplan.RpWeak(2, 0, pl, fw, fl, et, rasterplan.RiWitness(), 0, 2, owords, oruns, scr, ta, tb, tt), 1, "disagreeing witnesses: weak")
	// one disagreeing line alone is too little to say
	port.CellsDrop(oruns, 0)
	port.CellsDrop(owords, 0)
	rptReading(oruns, owords, rasterplan.RiWitness()+0, bw0, bw1)
	port.AssertEq(emonT, rasterplan.RpWeak(2, 0, pl, fw, fl, et, rasterplan.RiWitness(), 0, 1, owords, oruns, scr, ta, tb, tt), 0, "one compared line: not enough")
}
